def test_consume_prefix_in_state_dict_if_present():
    solution = Solution()

    # Test that the function works as expected when no keys have the prefix
    state_dict_no_prefix = {
        "key1": [1, 2, 3],
        "key2": {"a": 1}
    }
    prefix = "prefix."
    solution.consume_prefix_in_state_dict_if_present(state_dict_no_prefix, prefix)
    assert state_dict_no_prefix == {
        "key1": [1, 2, 3],
        "key2": {"a": 1}
    }

    # Test that the function removes the prefix from keys that match
    state_dict_with_prefix = {
        "prefix.key1": [1, 2, 3],
        "prefix.key2": {"a": 1},
        "other_key": [4, 5]
    }
    solution.consume_prefix_in_state_dict_if_present(state_dict_with_prefix, prefix)
    assert state_dict_with_prefix == {
        "key1": [1, 2, 3],
        "key2": {"a": 1},
        "other_key": [4, 5]
    }

    # Test that the function handles empty state_dict
    state_dict_empty = {}
    solution.consume_prefix_in_state_dict_if_present(state_dict_empty, prefix)
    assert state_dict_empty == {}

    # Test that the function handles an empty prefix
    state_dict_empty_prefix = {
        "key1": [1, 2, 3],
        "key2": {"a": 1}
    }
    solution.consume_prefix_in_state_dict_if_present(state_dict_empty_prefix, "")
    assert state_dict_empty_prefix == {
        "key1": [1, 2, 3],
        "key2": {"a": 1}
    }
