def test_check_symmetric():
    from unittest.mock import patch
    import numpy as np
    from scipy.sparse import csr_matrix
    class Solution:
        def check_symmetric(self, array, *, tol=1e-10, raise_warning=True, raise_exception=False):
            if hasattr(array, 'shape') and len(array.shape) != 2:
                raise ValueError("Array must be two-dimensional.")
            rows, cols = array.shape
            if rows != cols:
                raise ValueError("Array must be square.")

            is_symmetric = True
            if isinstance(array, np.ndarray):
                for i in range(rows):
                    for j in range(i + 1, cols):
                        if abs(array[i, j] - array[j, i]) > tol:
                            is_symmetric = False
                            break
                    if not is_symmetric:
                        break

                if not is_symmetric:
                    if raise_warning:
                        print("Warning: Array is not symmetric.") # Mocking warning behavior
                    if raise_exception:
                        raise Exception("Array is not symmetric.")
                    return (array + array.T) / 2.0
                else:
                    return array
            elif hasattr(array, 'tocsr'): # Assuming sparse matrix handling similar to NumPy logic for simplicity in this context
                 # Simplified symmetry check/symmetrization for testing purposes
                transposed = array.transpose()
                combined = array + transposed
                # In real scenario, need proper sparse summation/elimination
                # For testing, we assume successful return structure if inputs match expectations
                if not all((abs(array[i, j].data - transposed[i, j].data) < tol) for i in range(rows) for j in range(cols)): # Highly simplified check
                     if raise_warning:
                         print("Warning: Sparse array is not symmetric.")
                     if raise_exception:
                         raise Exception("Sparse array is not symmetric.")
                     return combined # Return sum approximation
                else:
                    return array


    solution=Solution()
    symmetric_array = np.array([[0., 1., 2.], [1., 0., 1.], [2., 1., 0.]])
    expected_output = np.array([[0., 1., 2.], [1., 0., 1.], [2., 1., 0.]])
    result = solution.check_symmetric(symmetric_array)
    np.testing.assert_allclose(result, expected_output)

